-- DT018: missing/empty tenant is denied, including ordinary pooled connections.
-- Stop old workers before applying; keep FORCE RLS. No role bypass is introduced.
DROP POLICY IF EXISTS tenant_isolation ON flow_brief_previews;
CREATE POLICY tenant_isolation ON flow_brief_previews USING (tenant_id = nullif(current_setting('app.tenant_id', true), '')) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true), ''));
